@@ -1,6 +1,21 @@
 import type { Provenance } from "./grade.ts";

-export const provenanceOf = (trailers: ReadonlyMap<string, string>): Provenance => {
+export interface CommitVerification {
+  gpgSigned: boolean;
+  signatureMatchesAuthor: boolean;
+}
+
+export const provenanceOf = (
+  trailers: ReadonlyMap<string, string>,
+  verification: CommitVerification
+): Provenance => {
+  // Never trust self-asserted provenance from commit trailers.
+  // Only elevate provenance from "unknown" via cryptographic verification.
+  if (!verification.gpgSigned || !verification.signatureMatchesAuthor) {
+    return "unknown";
+  }
+
+  // If signature is verified to match the author, check trailers for additional context.
   const raw = trailers.get("Provenance");
   if (raw === "authored" || raw === "inherited" || raw === "reconstructed") return raw;
   return "unknown";
